	<!-- jQuery + Owl -->
	<script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js"></script>
	<script src="https://cdnjs.cloudflare.com/ajax/libs/OwlCarousel2/2.3.4/owl.carousel.min.js"></script>
	<script>
		$(document).ready(function() {
			$(".service-list-2.owl-carousel").owlCarousel({
				loop: true,
				margin: 10,
				nav: true,
				dots: true,
				autoplay: true,
				autoplayTimeout: 3500,
				autoplayHoverPause: true,
				navText: ["&#8592;", "&#8594;"],
				responsive: {
					0: {
						items: 1
					},
					576: {
						items: 2
					},
					992: {
						items: 3
					}
				}
			});
		});

		// Mobile menu
		const ham = document.getElementById('ham');
		const nav = document.getElementById('mobileNav');
		ham.addEventListener('click', () => {
			ham.classList.toggle('open');
			nav.classList.toggle('open');
		});
		document.querySelectorAll('.nav_scroll .menu-item-has-children > a').forEach(a => {
			a.addEventListener('click', e => {
				e.preventDefault();
				a.parentElement.classList.toggle('open')
			});
		});

		// Scroll reveal
		const obs = new IntersectionObserver(entries => {
			entries.forEach(e => {
				if (e.isIntersecting) e.target.classList.add('visible')
			});
		}, {
			threshold: 0.1
		});
		document.querySelectorAll('.reveal').forEach(el => obs.observe(el));

		// FAQ accordion
		document.querySelectorAll('.faq-question').forEach(q => {
			q.addEventListener('click', () => {
				const parent = q.closest('.faq-singular');
				const isOpen = parent.classList.contains('active');
				document.querySelectorAll('.faq-singular').forEach(f => f.classList.remove('active'));
				if (!isOpen) parent.classList.add('active');
			});
		});
	</script>
